import { beforeEach, describe, expect, it, vi } from "vitest";
import { screen, waitFor } from "@testing-library/react";
import { userEvent } from "@testing-library/user-event";
import type { Conversation } from "../types";
import { ChatHeader } from "./ChatHeader";
import { renderWithProviders } from "../tests/utils";
import { COPY_BUTTON_TOOLTIP_COPIED } from "../constants";

const { mockCopyConversation, mockLogError, mockShowToast } = vi.hoisted(() => ({
  mockCopyConversation: vi.fn(),
  mockLogError: vi.fn(),
  mockShowToast: vi.fn(),
}));

vi.mock("../utils", () => ({
  copyConversation: mockCopyConversation,
  downloadRawTrackerLogs: vi.fn(),
  downloadE2eTests: vi.fn(),
}));

vi.mock("../InspectorContext", () => ({
  useInspectorContext: () => ({
    logError: mockLogError,
    showToast: mockShowToast,
    track: vi.fn(),
    onboardingTooltips: [],
  }),
}));

vi.mock("../OnboardingTooltip", () => ({
  OnboardingTooltip: ({ children }: { children: React.ReactNode }) => children,
}));

vi.mock("../PopoverMenu", () => ({
  PopoverMenu: ({ trigger, children }: { trigger: React.ReactNode; children: React.ReactNode }) => (
    <div>
      {trigger}
      {children}
    </div>
  ),
}));

vi.mock("../PopoverMenuItem", () => ({
  PopoverMenuItem: ({
    label,
    onClick,
    testId,
  }: {
    label: string;
    onClick: () => void;
    testId: string;
  }) => (
    <button data-testid={testId} onClick={onClick} type="button">
      {label}
    </button>
  ),
}));

vi.mock("../Tooltip", () => ({
  Tooltip: ({
    children,
    content,
    open,
  }: {
    children: React.ReactNode;
    content: React.ReactNode;
    open?: boolean;
  }) => (
    <div>
      {children}
      {open ? <span>{content}</span> : null}
    </div>
  ),
}));

const makeConversation = (totalNumberOfUserMessages: number): Conversation => ({
  id: "conv-1",
  startDate: new Date().toISOString(),
  reviewed: false,
  totalNumberOfUserMessages,
  events: [],
});

const renderChatHeader = (conversationList: Conversation[]) =>
  renderWithProviders(
    <ChatHeader
      onNewConversation={vi.fn()}
      flowView={false}
      setFlowView={vi.fn()}
      conversationList={conversationList}
      sessionId="session-1"
    />,
    { initialStoreState: { isEmbedded: false } },
  );

describe("ChatHeader", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockCopyConversation.mockResolvedValue(undefined);
  });

  it("disables copy button when there are no user messages", () => {
    renderChatHeader([makeConversation(0)]);

    expect(screen.getByTestId("copy-conversation-button")).toBeDisabled();
  });

  it("enables copy button when a conversation has user messages", () => {
    renderChatHeader([makeConversation(1)]);

    expect(screen.getByTestId("copy-conversation-button")).toBeEnabled();
  });

  it("calls copyConversation with current conversations when copy is clicked", async () => {
    const user = userEvent.setup();
    const conversations = [makeConversation(1), makeConversation(2)];
    renderChatHeader(conversations);

    await user.click(screen.getByTestId("copy-conversation-button"));

    expect(mockCopyConversation).toHaveBeenCalledOnce();
    expect(mockCopyConversation).toHaveBeenCalledWith(conversations);
  });

  it("shows copied feedback text after successful copy", async () => {
    const user = userEvent.setup();
    renderChatHeader([makeConversation(1)]);

    await user.click(screen.getByTestId("copy-conversation-button"));

    await waitFor(() => {
      expect(screen.getByText(COPY_BUTTON_TOOLTIP_COPIED)).toBeInTheDocument();
    });
  });

  it("logs and toasts when copy fails", async () => {
    const user = userEvent.setup();
    const copyError = new Error("clipboard unavailable");
    mockCopyConversation.mockRejectedValueOnce(copyError);
    renderChatHeader([makeConversation(1)]);

    await user.click(screen.getByTestId("copy-conversation-button"));

    await waitFor(() => {
      expect(mockLogError).toHaveBeenCalledWith(copyError, {
        tags: { component: "ChatHeader", action: "copyConversation" },
      });
    });
    expect(mockShowToast).toHaveBeenCalledWith({
      title: "Copy failed",
      description: "Could not copy conversation to clipboard.",
      type: "error",
    });
  });
});
